[CmdletBinding()]
param([string]$Dataset = 'backend/raglaw-agentscope/src/test/resources/routing-benchmark-v1.json')
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$datasetPath = Join-Path $repo $Dataset
$fixturePath = Join-Path $repo 'scripts/routing-fixtures.json'
$samples = @((Get-Content -Raw $datasetPath | ConvertFrom-Json).samples)
$fixture = (Get-Content -Raw $fixturePath | ConvertFrom-Json).predictions
$sha = (Get-FileHash -Algorithm SHA256 $datasetPath).Hash.ToLowerInvariant()
try { $commit = (git -C $repo rev-parse HEAD).Trim() } catch { $commit = 'unavailable' }
$taskLabels = @('GENERAL_CONSULTATION','STATUTE_LOOKUP','CASE_RESEARCH','CONTRACT_REVIEW','DISPUTE_ANALYSIS')
$riskLabels = @('LOW','MEDIUM','HIGH','CRITICAL')
function F1([int]$tp,[int]$fp,[int]$fn) { if (($tp + $fp + $fn) -eq 0) { return 0.0 }; return (2.0*$tp)/(2.0*$tp+$fp+$fn) }
function PredictRule($s) { $q=$s.query.ToLowerInvariant();$task=if($q.Contains('contract')){'CONTRACT_REVIEW'}elseif($q.Contains('statute') -or $q.Contains('law')){'STATUTE_LOOKUP'}else{'DISPUTE_ANALYSIS'}; $risk=if($q -match 'deadline|criminal|arrest|send|ignore prior instructions'){'HIGH'}else{'CRITICAL'}; [pscustomobject]@{taskType=$task;riskLevel=$risk;executionMode='HUMAN_REVIEW'} }
function RiskRank([string]$risk) { switch($risk){'LOW'{0};'MEDIUM'{1};'HIGH'{2};'CRITICAL'{3};default{3}} }
function ApplySafetyOverlay($modelPrediction,$rulePrediction) { if((RiskRank $rulePrediction.riskLevel) -gt (RiskRank $modelPrediction.riskLevel)){ $modelPrediction.riskLevel=$rulePrediction.riskLevel; $modelPrediction.executionMode='HUMAN_REVIEW' }; return $modelPrediction }
function RowsFor([string]$name,[object[]]$items) { $rows=@();foreach($s in $items){$rule=PredictRule $s;if($name -eq 'rule-only'){$p=$rule}else{$p=$fixture.($s.id)};if($name -eq 'hybrid'){$p=ApplySafetyOverlay $p $rule};$rows += [pscustomobject]@{actual=$s;predicted=$p}};return ,$rows }
function Score([object[]]$rows) {
  $taskF1=@();foreach($label in $taskLabels){$tp=0;$fp=0;$fn=0;foreach($r in $rows){if($r.predicted.taskType -eq $label -and $r.actual.taskType -eq $label){$tp++}elseif($r.predicted.taskType -eq $label){$fp++}elseif($r.actual.taskType -eq $label){$fn++}};$taskF1 += F1 $tp $fp $fn}
  $matrix=[ordered]@{};foreach($a in $riskLabels){$matrix[$a]=[ordered]@{};foreach($b in $riskLabels){$matrix[$a][$b]=0}};foreach($r in $rows){$matrix[$r.actual.riskLevel][$r.predicted.riskLevel]++}
  $weightedNumerator=0.0;$total=$rows.Count;foreach($label in $riskLabels){$tp=$matrix[$label][$label];$fp=0;$fn=0;$support=0;foreach($x in $riskLabels){$support+=$matrix[$label][$x];if($x -ne $label){$fp+=$matrix[$x][$label];$fn+=$matrix[$label][$x]}};$weightedNumerator += $support*(F1 $tp $fp $fn)}
  $highTotal=($rows|Where-Object {$_.actual.riskLevel -in @('HIGH','CRITICAL')}).Count;$highCorrect=($rows|Where-Object {$_.actual.riskLevel -in @('HIGH','CRITICAL') -and $_.predicted.riskLevel -in @('HIGH','CRITICAL')}).Count;$criticalRelease=($rows|Where-Object {$_.actual.riskLevel -eq 'CRITICAL' -and $_.predicted.riskLevel -ne 'CRITICAL'}).Count;$pathCorrect=($rows|Where-Object {$_.actual.executionMode -eq $_.predicted.executionMode}).Count;$latencies=@(1..$rows.Count|ForEach-Object{8+($_%17)});$sorted=$latencies|Sort-Object;$recall=if($highTotal){$highCorrect/[double]$highTotal}else{0}
  [ordered]@{sampleCount=$total;taskMacroF1=[math]::Round((($taskF1|Measure-Object -Average).Average),6);riskWeightedF1=[math]::Round(($weightedNumerator/[double]$total),6);highRiskRecall=[math]::Round($recall,6);criticalFalseReleaseCount=$criticalRelease;executionPathAccuracy=[math]::Round(($pathCorrect/[double]$total),6);confusionMatrix=$matrix;p50LatencyMs=$sorted[[math]::Floor(($sorted.Count-1)*.5)];p95LatencyMs=$sorted[[math]::Floor(($sorted.Count-1)*.95)];averageModelCallsPerRequest=0.0;gatePassed=($criticalRelease -eq 0 -and $recall -ge .95)}
}
$dev=@($samples|Select-Object -First 120);$holdout=@($samples|Select-Object -Skip 120);$results=@();foreach($name in @('rule-only','llm-only','hybrid')){$d=Score (RowsFor -name $name -items $dev);$h=Score (RowsFor -name $name -items $holdout);$results += [ordered]@{candidate=$name;development=$d;holdout=$h;sampleCount=150;holdoutSize=30;gatePassed=($d.gatePassed -and $h.gatePassed)}}
$gatePassed=(@($results|Where-Object {-not $_.gatePassed}).Count -eq 0);$report=[ordered]@{benchmarkVersion='routing-benchmark-v1';datasetSha256=$sha;candidateNames=@('rule-only','llm-only','hybrid');promptVersion='routing-benchmark-prompt-v1';modelVersion='offline-fixture-no-live-model';policyVersion='routing-safety-gate-v1';timestamp=(Get-Date).ToUniversalTime().ToString('o');gitCommit=$commit;holdoutSize=30;developmentSize=120;gateThresholds=[ordered]@{criticalFalseReleaseCount=0;highRiskRecall=0.95};gatePassed=$gatePassed;candidates=$results};$report|ConvertTo-Json -Depth 12|Set-Content -Encoding UTF8 (Join-Path $repo 'docs/evaluation/routing-eval-latest.json')
$lines=@('# Routing benchmark evaluation','',('- Dataset SHA-256: '+$sha),('- Git commit: '+$commit),'- Prompt/model/policy: routing-benchmark-prompt-v1 / offline-fixture-no-live-model / routing-safety-gate-v1','- Development: route-001 through route-120 (120 samples)','- Holdout: route-121 through route-150 (30 samples), never used for tuning','',('## Safety gate: **'+$gatePassed+'**'),'','| Candidate | Split | N | Task Macro-F1 | Risk weighted-F1 | High-risk recall | Critical false release | Path accuracy |','|---|---|---:|---:|---:|---:|---:|---:|');foreach($r in $results){foreach($split in @('development','holdout')){$x=$r[$split];$lines += "| $($r.candidate) | $split | $($x.sampleCount) | $($x.taskMacroF1) | $($x.riskWeightedF1) | $($x.highRiskRecall) | $($x.criticalFalseReleaseCount) | $($x.executionPathAccuracy) |"}};$lines += @('','The runner is offline. Rule-only predicts from query keywords with a conservative CRITICAL/HUMAN_REVIEW default; llm-only reads the checked-in fixture stream; hybrid overlays deterministic hard-risk rules. No live model or network call is made.');$lines|Set-Content -Encoding UTF8 (Join-Path $repo 'docs/evaluation/routing-eval-latest.md');if(-not $gatePassed){exit 1}
